+	selector := strings.TrimSpace(args[0])
+	commentID := strings.TrimSpace(args[1])
+	if selector == "" {
+		return "", "", errors.New("trail selector cannot be empty")
+	}
+	if commentID == "" {
+		return "", "", errors.New("finding id cannot be empty")
+	}
